// Generated by allium:propagate from spec/recipe-ideas.allium (archived_at, ArchiveIdea, RestoreIdea and the
// requires: idea.archived_at = null on EditIdea and PickCandidate). Do not edit by hand: change the spec and propagate.
import { describe, expect, it } from "vitest";
import {
  archiveIdea,
  defaultIdeaConfig,
  editIdea,
  isStale,
  keepIdea,
  noteIdea,
  pickCandidate,
  recipeIdeaId,
  restoreIdea,
  type CandidateProposal,
  type IdeaConfig,
  type RecipeIdea,
} from "../../src/ideas/idea.js";
import * as domain from "../../src/index.js";
import { memberId } from "../../src/shared/ids.js";
import type { Result } from "../../src/shared/result.js";

const ME = memberId("me");
const AC = memberId("AC");
const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const WEEK = 7 * 24 * HOUR;
const T0 = Date.parse("2026-11-01T12:00:00Z");

const must = <T>(r: Result<T>): T => {
  if (!r.ok) throw new Error(`rejected: ${r.reason}`);
  return r.value;
};

const anIdea = (over: Partial<RecipeIdea> = {}): RecipeIdea => ({
  ...must(noteIdea({ id: recipeIdeaId("i1"), member: ME, title: "Kürbisgnocchi" }, T0)),
  ...over,
});

/** An idea put aside at `at`, built from the field alone so the refusals do not depend on archiveIdea. */
const anArchivedIdea = (at: number, over: Partial<RecipeIdea> = {}): RecipeIdea => anIdea({ archivedAt: at, ...over });

const proposal = (n: number): CandidateProposal => ({
  title: `Rezept ${n}`,
  link: `https://example.org/rezept-${n}`,
  summary: `Kurz ${n}`,
});

const full = () =>
  anIdea({
    note: "Hokkaido aus dem Garten",
    inspirationLink: "https://example.org/insta",
    candidates: [proposal(1), proposal(2)],
    lastTouchedAt: T0 + WEEK,
  });

describe("RecipeIdea.archived_at", () => {
  it("is exported from the domain package with archiveIdea and restoreIdea", () => {
    expect(typeof domain.archiveIdea).toBe("function");
    expect(typeof domain.restoreIdea).toBe("function");
  });

  it("is null for a newly noted idea: it is in the list", () => {
    const idea = must(noteIdea({ id: recipeIdeaId("i1"), member: ME, title: "Kürbisgnocchi" }, T0));
    expect(idea).toHaveProperty("archivedAt", null);
  });
});

describe("rule ArchiveIdea", () => {
  it("puts the idea aside at this moment and leaves everything else, the clock included, as it was", () => {
    const idea = full();
    const now = T0 + 3 * WEEK;
    expect(must(archiveIdea(idea, { member: AC }, now))).toEqual({
      ...idea,
      archivedAt: now,
    });
  });

  it("lets either member archive any idea, whoever noted it", () => {
    const now = T0 + HOUR;
    expect(must(archiveIdea(anIdea(), { member: ME }, now)).archivedAt).toBe(now);
    expect(must(archiveIdea(anIdea(), { member: AC }, now)).archivedAt).toBe(now);
  });

  it("archives a stale idea, which then is no longer stale", () => {
    const now = T0 + 10 * WEEK;
    expect(isStale(anIdea(), now, defaultIdeaConfig)).toBe(true);
    const archived = must(archiveIdea(anIdea(), { member: ME }, now));
    expect(archived.lastTouchedAt).toBe(T0);
    expect(isStale(archived, now, defaultIdeaConfig)).toBe(false);
  });

  it("is rejected for an idea that is already archived", () => {
    const archived = anArchivedIdea(T0 + HOUR);
    expect(archiveIdea(archived, { member: ME }, T0 + 2 * HOUR)).toEqual({
      ok: false,
      reason: "already_archived",
    });
  });
});

describe("rule RestoreIdea", () => {
  it("brings the idea back and starts its clock again, keeping note, link and candidates", () => {
    const idea = anArchivedIdea(T0 + 2 * WEEK, {
      note: "Hokkaido",
      inspirationLink: "https://example.org/insta",
      candidates: [proposal(1)],
    });
    const now = T0 + 30 * WEEK;
    expect(must(restoreIdea(idea, { member: AC }, now))).toEqual({
      ...idea,
      archivedAt: null,
      lastTouchedAt: now,
    });
  });

  it("does not bring an old idea back stale", () => {
    const now = T0 + 52 * WEEK;
    const restored = must(restoreIdea(anArchivedIdea(T0 + HOUR), { member: ME }, now));
    expect(isStale(restored, now, defaultIdeaConfig)).toBe(false);
    expect(isStale(restored, now + 8 * WEEK, defaultIdeaConfig)).toBe(true);
  });

  it("is rejected for an idea that is not archived", () => {
    expect(restoreIdea(anIdea(), { member: ME }, T0 + HOUR)).toEqual({
      ok: false,
      reason: "not_archived",
    });
  });
});

describe("derived is_stale with archived_at", () => {
  const config = defaultIdeaConfig;

  it("is false for an archived idea however long ago it was touched", () => {
    const archived = anArchivedIdea(T0 + HOUR);
    expect(isStale(archived, T0 + 8 * WEEK, config)).toBe(false);
    expect(isStale(archived, T0 + 500 * WEEK, config)).toBe(false);
    expect(
      isStale(archived, T0 + 2 * HOUR, {
        ...config,
        ideaStaleAfterMs: 0,
      } satisfies IdeaConfig),
    ).toBe(false);
  });

  it("is unchanged for an idea in the list: true once the stale period has passed", () => {
    expect(isStale(anIdea({ archivedAt: null }), T0 + 8 * WEEK, config)).toBe(true);
    expect(isStale(anIdea({ archivedAt: null }), T0 + 8 * WEEK - 1, config)).toBe(false);
  });
});

describe("rule KeepIdea on an archived idea", () => {
  it("is rejected: an archived idea is never stale, so it cannot be kept", () => {
    const archived = anArchivedIdea(T0 + HOUR);
    expect(keepIdea(archived, { member: ME }, T0 + 20 * WEEK, defaultIdeaConfig)).toEqual({
      ok: false,
      reason: "not_stale",
    });
  });
});

describe("requires: idea.archived_at = null", () => {
  it("EditIdea is rejected for an archived idea", () => {
    const archived = anArchivedIdea(T0 + HOUR, { note: "alt" });
    expect(editIdea(archived, { member: AC, title: "Kürbisgnocchi mit Salbei", note: "neu" }, T0 + WEEK)).toEqual({
      ok: false,
      reason: "archived",
    });
  });

  it("EditIdea refuses the archived idea before looking at the title", () => {
    expect(editIdea(anArchivedIdea(T0 + HOUR), { member: ME, title: "" }, T0 + WEEK)).toEqual({
      ok: false,
      reason: "archived",
    });
  });

  it("PickCandidate is rejected for a candidate of an archived idea", () => {
    const archived = anArchivedIdea(T0 + HOUR, {
      candidates: [proposal(1), proposal(2)],
    });
    expect(pickCandidate(archived, { member: AC, candidate: 1 }, T0 + WEEK)).toEqual({ ok: false, reason: "archived" });
  });

  it("EditIdea and PickCandidate work again once the idea is restored", () => {
    const restored = must(
      restoreIdea(anArchivedIdea(T0 + HOUR, { candidates: [proposal(1)] }), { member: ME }, T0 + WEEK),
    );
    expect(must(editIdea(restored, { member: AC, title: "Neu" }, T0 + 2 * WEEK)).title).toBe("Neu");
    expect(must(pickCandidate(restored, { member: AC, candidate: 0 }, T0 + 2 * WEEK)).source).toBe(
      "https://example.org/rezept-1",
    );
  });
});
